import { SidebarLeft01Icon } from "@hugeicons/core-free-icons"
import { Drawer, DrawerBackdrop, DrawerContent, DrawerTitle } from "@ui-sdk/react/drawer"
import { createContext, type ReactNode, useContext, useEffect, useRef, useState } from "react"
import { Button } from "@/components/ui/button"
import { Icon } from "@/components/ui/icon"
import {
  createResizableController,
  Resizable,
  ResizableHandle,
  ResizablePanel,
  type ResizableController,
} from "@/components/ui/resizable"
import { Tooltip, TooltipContent, TooltipShortcut, TooltipTrigger } from "@/components/ui/tooltip"
import { useMediaQuery } from "@/lib/use-media-query"
import { cn } from "@/lib/utils"

interface AppShellContextValue {
  sidebar: ResizableController
  /** True while the desktop sidebar is collapsed to its icon rail. */
  collapsed: boolean
  /** True below the breakpoint, where the sidebar is a drawer over the page. */
  isMobile: boolean
  /** Whether the sidebar is showing: expanded on desktop, open as a drawer on mobile. */
  sidebarOpen: boolean
  toggleSidebar: () => void
  /** Closes the drawer on mobile. Does nothing on desktop, where the sidebar stays put. */
  closeSidebar: () => void
}

const AppShellContext = createContext<AppShellContextValue | null>(null)

export function useAppShell() {
  const context = useContext(AppShellContext)
  if (!context) throw new Error("useAppShell must be used inside <AppShell>")
  return context
}

/** Like useAppShell, but returns null outside an AppShell instead of throwing. */
export function useOptionalAppShell() {
  return useContext(AppShellContext)
}

const SIDEBAR_ID = "app-shell-sidebar"

interface AppShellProps {
  /** Runs the full height of the window, beside the main area. */
  sidebar: ReactNode
  children: ReactNode
  /** On mobile, shown beside the sidebar button in the slim bar above the main area, like a page title. */
  mobileHeader?: ReactNode
  /** Saves the sidebar width under this key. */
  autoSaveId?: string
  /** Below this viewport width, in pixels, the sidebar becomes a drawer. */
  breakpoint?: number
  /** Names the sidebar drawer for screen readers. */
  sidebarLabel?: string
  /** Toggles the sidebar with Command+B, or Ctrl+B outside Apple platforms. */
  shortcut?: boolean
  className?: string
}

/**
 * A window frame: a full-height sidebar with the main area beside it, and no header.
 * On wide screens the sidebar resizes and collapses to an icon rail; on narrow ones it is a
 * drawer that slides over the page, opened from a slim bar holding the sidebar button.
 */
export function AppShell({
  sidebar,
  children,
  mobileHeader,
  autoSaveId,
  breakpoint = 768,
  sidebarLabel = "Sidebar",
  shortcut = true,
  className,
}: AppShellProps) {
  const [controller] = useState(createResizableController)
  const [collapsed, setCollapsed] = useState(false)
  const [drawerOpen, setDrawerOpen] = useState(false)
  const isMobile = useMediaQuery(`(max-width: ${breakpoint - 1}px)`)

  useEffect(() => {
    if (!isMobile) setDrawerOpen(false)
  }, [isMobile])

  const toggleSidebar = () => {
    if (isMobile) setDrawerOpen((open) => !open)
    else if (controller.isCollapsed(SIDEBAR_ID)) controller.expand(SIDEBAR_ID)
    else controller.collapse(SIDEBAR_ID)
  }

  const toggleRef = useRef(toggleSidebar)
  toggleRef.current = toggleSidebar
  useEffect(() => {
    if (!shortcut) return
    const onKey = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && !event.altKey && event.key.toLowerCase() === "b") {
        event.preventDefault()
        toggleRef.current()
      }
    }
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [shortcut])

  const value: AppShellContextValue = {
    sidebar: controller,
    collapsed: !isMobile && collapsed,
    isMobile,
    sidebarOpen: isMobile ? drawerOpen : !collapsed,
    toggleSidebar,
    closeSidebar: () => setDrawerOpen(false),
  }

  return (
    <AppShellContext.Provider value={value}>
      <div
        data-slot="app-shell"
        data-mobile={isMobile ? "" : undefined}
        className={cn("flex h-full flex-col bg-background text-foreground", className)}
      >
        {isMobile ? (
          <>
            <div
              data-slot="app-shell-mobile-bar"
              className="flex h-titlebar shrink-0 items-center gap-1 border-b border-border bg-sidebar px-2"
            >
              <SidebarToggle />
              <div className="min-w-0 flex-1 truncate px-1 text-ui font-medium">{mobileHeader}</div>
            </div>
            <div className="min-h-0 flex-1">{children}</div>
            <Drawer side="left" open={drawerOpen} onOpenChange={setDrawerOpen}>
              <DrawerBackdrop className="fixed inset-0 bg-black/30 dark:bg-black/50" />
              <DrawerContent className="h-full w-[min(300px,85vw)] border-r border-border bg-sidebar shadow-popover outline-none">
                <DrawerTitle className="sr-only">{sidebarLabel}</DrawerTitle>
                {sidebar}
              </DrawerContent>
            </Drawer>
          </>
        ) : (
          <Resizable
            controller={controller}
            autoSaveId={autoSaveId}
            onLayoutChange={() => setCollapsed(controller.isCollapsed(SIDEBAR_ID))}
            className="min-h-0 flex-1"
          >
            <ResizablePanel
              id={SIDEBAR_ID}
              defaultSize="260px"
              minSize="200px"
              maxSize="420px"
              collapsible
              collapsedSize="52px"
              className="bg-sidebar"
            >
              {sidebar}
            </ResizablePanel>
            <ResizableHandle aria-label="Resize sidebar" />
            <ResizablePanel minSize="360px">{children}</ResizablePanel>
          </Resizable>
        )}
      </div>
    </AppShellContext.Provider>
  )
}

export function SidebarToggle({ className }: { className?: string }) {
  const { toggleSidebar, sidebarOpen, isMobile } = useAppShell()
  const label = sidebarOpen ? "Hide sidebar" : isMobile ? "Open sidebar" : "Show sidebar"
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button
            variant="ghost"
            size="icon-sm"
            className={className}
            onClick={toggleSidebar}
            aria-pressed={sidebarOpen}
          />
        }
      >
        <Icon icon={SidebarLeft01Icon} />
      </TooltipTrigger>
      <TooltipContent side="bottom">
        {label}
        <TooltipShortcut>⌘B</TooltipShortcut>
      </TooltipContent>
    </Tooltip>
  )
}

import { Button as ButtonPrimitive } from "@ui-sdk/react/button"
import type { ComponentProps, ReactNode } from "react"
import { useOptionalAppShell } from "@/components/shell/app-shell"
import { ScrollArea } from "@/components/ui/scroll-area"
import { cn, withClass } from "@/lib/utils"

// In an AppShell, a collapsed desktop sidebar becomes a narrow icon rail. Parts below style the
// rail with group-data-collapsed/sidebar: labels turn screen-reader-only and items center their icon.
export function Sidebar({ className, ...props }: ComponentProps<"nav">) {
  const shell = useOptionalAppShell()
  return (
    <nav
      data-slot="sidebar"
      data-collapsed={shell?.collapsed ? "" : undefined}
      className={cn("group/sidebar flex size-full min-w-0 flex-col", className)}
      {...props}
    />
  )
}

/** The top of the sidebar, like the product name beside the sidebar toggle. */
export function SidebarHeader({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      className={cn(
        "flex h-titlebar shrink-0 items-center gap-1 px-2",
        `group-data-collapsed/sidebar:justify-center group-data-collapsed/sidebar:px-0`,
        className,
      )}
      {...props}
    />
  )
}

/** Text hidden while the sidebar is a rail, like the product name. */
export function SidebarTitle({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      className={cn("flex min-w-0 flex-1 items-center gap-2 px-1 text-ui font-semibold", `group-data-collapsed/sidebar:hidden`, className)}
      {...props}
    />
  )
}

export function SidebarContent({ className, children }: { className?: string; children: ReactNode }) {
  return (
    <ScrollArea className={cn("flex-1", className)}>
      <div className={cn("flex flex-col gap-3 px-2 pb-2", `group-data-collapsed/sidebar:px-1.5`)}>{children}</div>
    </ScrollArea>
  )
}

export function SidebarFooter({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      className={cn("flex shrink-0 flex-col gap-px border-t border-border p-2", `group-data-collapsed/sidebar:px-1.5`, className)}
      {...props}
    />
  )
}

interface SidebarGroupProps extends ComponentProps<"div"> {
  label?: string
  /** Hides the whole group while the sidebar is a rail, for items without icons, like recent documents. */
  hideOnRail?: boolean
}

export function SidebarGroup({ label, hideOnRail, className, children, ...props }: SidebarGroupProps) {
  return (
    <div
      role="group"
      aria-label={label}
      className={cn("flex flex-col gap-px", hideOnRail && `group-data-collapsed/sidebar:hidden`, className)}
      {...props}
    >
      {label && (
        <div className={cn("px-2 pb-1 pt-1 text-2xs font-medium text-subtle-foreground", `group-data-collapsed/sidebar:hidden`)}>{label}</div>
      )}
      {children}
    </div>
  )
}

type SidebarItemProps = ComponentProps<typeof ButtonPrimitive> & {
  active?: boolean
  /**
   * Whether pressing it closes the sidebar drawer on mobile. Defaults to true, for navigation.
   * Pass false for items that open something in place, like a menu trigger.
   */
  closesSidebar?: boolean
}

/**
 * A row in the sidebar: an icon and a label in a span. Render it as a link with
 * `render={<a href="…" />}`. On the rail, span labels become screen-reader-only.
 */
export function SidebarItem({ className, active, closesSidebar = true, onClick, ...props }: SidebarItemProps) {
  const shell = useOptionalAppShell()
  return (
    <ButtonPrimitive
      onClick={(event, details) => {
        const result = onClick?.(event, details)
        if (closesSidebar && shell?.isMobile) shell.closeSidebar()
        return result
      }}
      data-active={active ? "" : undefined}
      aria-current={active ? "page" : undefined}
      className={withClass(
        cn(
          "flex h-control w-full min-w-0 cursor-default select-none items-center gap-2 rounded-md px-2 text-left text-ui text-muted-foreground no-underline outline-none transition-colors hover:bg-accent hover:text-foreground data-active:bg-accent data-active:text-foreground [&_svg]:size-4 [&_svg]:shrink-0 [&>span]:truncate",
          `group-data-collapsed/sidebar:justify-center group-data-collapsed/sidebar:px-0 group-data-collapsed/sidebar:[&>span:not([data-slot=avatar])]:sr-only group-data-collapsed/sidebar:[&>[data-sidebar-trailing]]:hidden`,
        ),
        className,
      )}
      {...props}
    />
  )
}

/** Something at the end of an item, like a shortcut or a chevron. Hidden on the rail. */
export function SidebarItemTrailing({ className, ...props }: ComponentProps<"span">) {
  return (
    <span
      data-sidebar-trailing=""
      className={cn("ml-auto flex shrink-0 items-center text-2xs text-subtle-foreground", className)}
      {...props}
    />
  )
}

import type { ComponentProps } from "react"
import { cn } from "@/lib/utils"

/** The inside of a dock panel: an optional toolbar over a scrolling body. */
export function Panel({ className, ...props }: ComponentProps<"div">) {
  return <div data-slot="panel" className={cn("flex size-full min-h-0 flex-col bg-surface", className)} {...props} />
}

export function PanelToolbar({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="panel-toolbar"
      className={cn("flex h-9 shrink-0 items-center gap-1 border-b border-border px-2 text-ui text-muted-foreground", className)}
      {...props}
    />
  )
}

export function PanelBody({ className, ...props }: ComponentProps<"div">) {
  return <div data-slot="panel-body" className={cn("min-h-0 flex-1 overflow-auto", className)} {...props} />
}

import { useSyncExternalStore } from "react"

export function useMediaQuery(query: string) {
  return useSyncExternalStore(
    (onChange) => {
      const list = matchMedia(query)
      list.addEventListener("change", onChange)
      return () => list.removeEventListener("change", onChange)
    },
    () => matchMedia(query).matches,
    () => false,
  )
}
